INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(16301, 'Proverbs 31:7', 'Proverbs', 31, 7, '&nbsp;دوئ پرېږده چې ځان نشه کړى او چې خپله غريبى پرې هېره کړى چې خپل غم ورنه هېر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16302, 'Proverbs 31:8', 'Proverbs', 31, 8, '&nbsp;د هغوئ په ځائ خبرې کوه څوک چې د خپل ځان دپاره خبره نۀ شى کولے. او د هغه ټولو خلقو د حق دپاره څوک چې مسکينان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16303, 'Proverbs 31:9', 'Proverbs', 31, 9, '&nbsp;خبره کوه او په اِنصاف سره عدالت کوه، د غريب او حاجتمند د حق حِفاظت وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16304, 'Proverbs 31:10', 'Proverbs', 31, 10, '&nbsp;يوه پاکه او عزتمنده ښځه څوک پېدا کولے شى؟ هغه د لعلونو نه زياته قيمتى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16305, 'Proverbs 31:11', 'Proverbs', 31, 11, '&nbsp;د خاوند په هغې باندې پوره باور وى، او هغه به دے د څۀ محتاجه نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16306, 'Proverbs 31:12', 'Proverbs', 31, 12, '&nbsp;په خپل ټول عمر کښې به دا هغۀ ته فائده ورکوى او نقصان به نۀ ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16307, 'Proverbs 31:13', 'Proverbs', 31, 13, '&nbsp;هغه سنډ او وړۍ پېدا کوى او د هغې نه په خپلو لاسونو په خوشحالۍ سره کپړې جوړوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16308, 'Proverbs 31:14', 'Proverbs', 31, 14, '&nbsp;هغه د سوداګرو د سمندرى جهاز په شان وى، څوک چې خپل خوراک د لرې نه راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16309, 'Proverbs 31:15', 'Proverbs', 31, 15, '&nbsp;هغه سحر وختى راپاڅى لا چې تيارۀ وى او د خپل خاندان دپاره خوراک تياروى او خپلو وينځو ته کار ورښائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16310, 'Proverbs 31:16', 'Proverbs', 31, 16, '&nbsp;د زيات سوچ کولو نه وروستو هغه چرته زمکه خوښوى او په بيعه يې اخلى او د خپلې ګټې او محنت په پېسو پکښې د انګور باغ لګوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16311, 'Proverbs 31:17', 'Proverbs', 31, 17, '&nbsp;هغه خپل کار په ډېر محنت او د زړۀ نه کوى، او د هغې مټې د خپل کار پوره کولو دپاره مضبوطې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16312, 'Proverbs 31:18', 'Proverbs', 31, 18, '&nbsp;هغه په دې پوهيږى چې روزګار يې ګټه کوى، نو په شپه کښې تر ناوخته کار کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16313, 'Proverbs 31:19', 'Proverbs', 31, 19, '&nbsp;هغه په خپلو لاسونو سره څرخه کوى او دوک په خپلو ګوتو سره نيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16314, 'Proverbs 31:20', 'Proverbs', 31, 20, '&nbsp;هغه خپل لاسونه د غريبانانو مدد دپاره غزوى او حاجتمندو ته خپل لاسونه ورسوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16315, 'Proverbs 31:21', 'Proverbs', 31, 21, '&nbsp;کله چې واوره وريږى نو د هغې سره د خپل خاندان څۀ فکر نۀ وى، ځکه چې هغې دوئ ته ګرمې جامې تيارې کړى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16316, 'Proverbs 31:22', 'Proverbs', 31, 22, '&nbsp;هغه د خپل کټ دپاره څادر او د خپل ځان دپاره نازکې او رنګارنګ کپړې تياروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16317, 'Proverbs 31:23', 'Proverbs', 31, 23, '&nbsp;د هغې خاوند ته په جرګه کښې عزت ملاويږى، کله چې هم دے د ښار د مشرانو سره ناست وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16318, 'Proverbs 31:24', 'Proverbs', 31, 24, '&nbsp;هغه د کتان جامې جوړوى او خرڅوى، او تاجرانو ته يې د پټۍ په شکل کښې هم ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16319, 'Proverbs 31:25', 'Proverbs', 31, 25, '&nbsp;هغه د طاقت او وقار په لباس ملبوسه ده او د راتلونکو ورځو په حقله هغه خاندى او بې‌فکره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16320, 'Proverbs 31:26', 'Proverbs', 31, 26, '&nbsp;هغه په حِکمت سره خبرې کوى، او هغه په مهربانۍ سره ښودنه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16321, 'Proverbs 31:27', 'Proverbs', 31, 27, '&nbsp;هغه د خپل کور په حالاتو او سامان باندې خيال ساتى او د ناراستۍ روټۍ نۀ خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16322, 'Proverbs 31:28', 'Proverbs', 31, 28, '&nbsp;د هغې بچى چې راپاڅى نو دې ته برکت ورکوى او خاوند يې هم صِفت کوى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16323, 'Proverbs 31:29', 'Proverbs', 31, 29, '&nbsp;”ډيرې ښځې دى چې د عزت او درانۀ کارونه کوى، خو تۀ د دې ټولو نه ښۀ يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16324, 'Proverbs 31:30', 'Proverbs', 31, 30, '&nbsp;نازونه اداګانې دوکه ده او حُسن فانى دے، خو کومه ښځه چې د مالِک خُدائ نه يريږى نو هغه د صِفت قابله ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16325, 'Proverbs 31:31', 'Proverbs', 31, 31, '&nbsp;کوم کارونه چې هغې کړى دى هغې ته يې اجر ورکړئ، او د خلقو په مينځ کښې د هغې د محنت ستائينه وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16326, 'Ecclesiastes 1:1', 'Ecclesiastes', 1, 1, '&nbsp;دا د معلِم خبرې دى، چې د داؤد زوئ وو او د يروشلم بادشاه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16327, 'Ecclesiastes 1:2', 'Ecclesiastes', 1, 2, '&nbsp;هغه معلِم فرمائى، ژوند يو غټ راز دے، او زمونږ پوهه د دې په حقله ډېره محدوده ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16328, 'Ecclesiastes 1:3', 'Ecclesiastes', 1, 3, '&nbsp;په مخ د زمکې خلق دومره خوارى کوى نو د دې نه دوئ تۀ فائده څۀ ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16329, 'Ecclesiastes 1:4', 'Ecclesiastes', 1, 4, '&nbsp;پيړۍ په پيړۍ تېرې شى، خو زمکه همېشه قائمه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16330, 'Ecclesiastes 1:5', 'Ecclesiastes', 1, 5, '&nbsp;نمر راوخېژى او پرېوځى او هغه ځائ ته زر زر بيا ځى چې د کوم ځائ نه راخيژى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16331, 'Ecclesiastes 1:6', 'Ecclesiastes', 1, 6, '&nbsp;هوا د جنوب طرف ته چليږى، بيا تاو شى او د شمال طرف ته چليږى، دا ګېرچاپېره تاويږى راتاويږى او ځى راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16332, 'Ecclesiastes 1:7', 'Ecclesiastes', 1, 7, '&nbsp;ټول سيندونه سمندر ته بهيږى، خو سمندر ډک نۀ شو. ځکه چې د سيندونو اوبۀ د کوم ځائ نه بهيږى نو هم هلته مسلسل واپس راځى او بيا د هغه ځائ نه بهيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16333, 'Ecclesiastes 1:8', 'Ecclesiastes', 1, 8, '&nbsp;ټول څيزونه دومره د خوارۍ ډک دى چې انسان يې بيانولے نۀ شى. نۀ سترګې په کتلو مړيږى، او نۀ غوږونه په اورېدو ډکيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16334, 'Ecclesiastes 1:9', 'Ecclesiastes', 1, 9, '&nbsp;څۀ چې مخکښې وُو دا به بيا هم وى، څۀ چې شوى دى هغه به بيا هم کيږى. په مخ د زمکې هيڅ هم نوى نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16335, 'Ecclesiastes 1:10', 'Ecclesiastes', 1, 10, '&nbsp;کله کله خلق وائى، ”ګوره، دا يو نوے څيز دے.“ خو په اصل کښې دا زوړ وى، يو څيز هم په رښتيا نوے نۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16336, 'Ecclesiastes 1:11', 'Ecclesiastes', 1, 11, '&nbsp;هيچا ته ياد نۀ دى چې په تېرو وختونو کښې څۀ شوى وُو او څۀ چې اوس کيږى هغه به د راتلونکى وخت خلقو ته ياد نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16337, 'Ecclesiastes 1:12', 'Ecclesiastes', 1, 12, '&nbsp;زۀ معلِم په يروشلم کښې د بنى اِسرائيلو بادشاه وم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16338, 'Ecclesiastes 1:13', 'Ecclesiastes', 1, 13, '&nbsp;ما پوره عقل سره تلاش شروع کړو چې زۀ به حکمت سره هغه هر څۀ وګورم او معلوم به يې کړم کوم چې په دُنيا کښې شوى دى. نو زۀ دې نتيجې ته ورسېدم چې خُدائ پاک انسان ته د مشکل مشقت ذمه وارى ورکړې ده چې مصروف يې وساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16339, 'Ecclesiastes 1:14', 'Ecclesiastes', 1, 14, '&nbsp;ما هغه هر څۀ وليدل چې په مخ د زمکې شوى دى او زۀ تا ته وايم، چې دا هر څۀ بې‌معنې دى او هوا پسې منډې وهل دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16340, 'Ecclesiastes 1:15', 'Ecclesiastes', 1, 15, '&nbsp;څۀ چې غلط دى هغه ټيک کېدے نۀ شى، او د څۀ چې کمے دے نو هغه پېدا کېدے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16341, 'Ecclesiastes 1:16', 'Ecclesiastes', 1, 16, '&nbsp;ما خپل ځان سره ووئيل، ”زۀ د هغه ټولو نه ډېر زيات هوښيار يم چا چې زما نه مخکښې په يروشلم بادشاهى کړې ده. ما ډېر حِکمت او عِلم حاصل کړے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16342, 'Ecclesiastes 1:17', 'Ecclesiastes', 1, 17, '&nbsp;ما خپل پوره ذهنى طاقت په دې ولګولو چې حِکمت وپېژنم، او هم په ليونتوب او بې‌وقوفتوب پوهه شم، خو ما ته پته ولګېده چې دا ټول هم هوا پسې منډې وهل دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16343, 'Ecclesiastes 1:18', 'Ecclesiastes', 1, 18, '&nbsp;ځکه چرته چې حِکمت زيات وى هلته پرېشانى هم زياته وى، او څوک چې عِلم زياتوى هغه غمونه زياتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16344, 'Ecclesiastes 2:1', 'Ecclesiastes', 2, 1, '&nbsp;ما خپل زړۀ کښې ووئيل چې، ”عېش عشرت به وکړم او ښۀ مزې به وکړم،“ خو پته راته ولګېده چې دا هم بې‌معنې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16345, 'Ecclesiastes 2:2', 'Ecclesiastes', 2, 2, '&nbsp;نو ما ووئيل چې، ”خندا کم عقلتوب دے او عېش عشرت چا له څۀ ورکوى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16346, 'Ecclesiastes 2:3', 'Ecclesiastes', 2, 3, '&nbsp;د ډېر سوچ نه پس ما فېصله وکړه چې د ميو په ذريعه ځان په سُر کښې کړم. او د حکمت په لټون کښې مې کم عقلتوب شروع کړو. ما غوښتل چې معلوم کړم چې د انسان په دوه څلور ورځې ژوند کښې په مخ د زمکې څۀ کول فائده مند دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16347, 'Ecclesiastes 2:4', 'Ecclesiastes', 2, 4, '&nbsp;ما لوئ لوئ کارونه وکړل. ما د ځان دپاره کورونه جوړ کړل او د انګورو باغونه مې وکَرل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16348, 'Ecclesiastes 2:5', 'Ecclesiastes', 2, 5, '&nbsp;ما د ځان دپاره چمنونه او باغونه جوړ کړل، او په هغې کښې مې هر قِسمه د مېوو ونې ولګولې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16349, 'Ecclesiastes 2:6', 'Ecclesiastes', 2, 6, '&nbsp;ما تالابونه جوړ کړل چې د هغې په ذريعه دا ډيرې ونې اوبۀ کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16350, 'Ecclesiastes 2:7', 'Ecclesiastes', 2, 7, '&nbsp;ما ډېر غلامان او وينځې واخستلې، او زما په کور کښې هم غلامان پېدا شوى وُو. ما سره دومره زيات څاروى وُو چې په يروشلم کښې پخوانى يو بادشاه سره هم نۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16351, 'Ecclesiastes 2:8', 'Ecclesiastes', 2, 8, '&nbsp;ما د خپل ځان دپاره سپين زر، سرۀ زر، او د بادشاهانو او صوبو خزانې راټولې کړې. ما سره سندرغاړى سړى او ښځې وې، او ما سره نورې داسې ډېرې ښائسته وينځې وې چې سړے يې ارمان کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16352, 'Ecclesiastes 2:9', 'Ecclesiastes', 2, 9, '&nbsp;نو داسې زۀ د هغه ټولو نه لوئ سړے شوم څوک چې زما نه مخکښې په يروشلم کښې تېر شوى وُو، او ما خپل حِکمت جارى ساتلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16353, 'Ecclesiastes 2:10', 'Ecclesiastes', 2, 10, '&nbsp;ما چې څۀ هم غوښتل نو هغه ما اخستى وُو. ما د خپل ځان نه د يوې خوشحالۍ اِنکار هم نۀ وو کړے. ما چې کوم محنت کړے وو نو زۀ په هغې باندې خوشحاله وم، او دا خوشحالى زما د هغه محنت اِنعام وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16354, 'Ecclesiastes 2:11', 'Ecclesiastes', 2, 11, '&nbsp;خو څنګه چې ما هغه هر څۀ ته وکتل د څۀ حاصلولو دپاره چې ما ډېر محنت کړے وو، نو دا هر څۀ بې‌معنې وُو، داسې لکه چې هوا پسې منډې وهى. او په مخ د زمکې د هيڅ کار هم څۀ فائده نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16355, 'Ecclesiastes 2:12', 'Ecclesiastes', 2, 12, '&nbsp;نو ما فېصله وکړه چې په حِکمت، کم عقلتوب او په ليونتوب غور وکړم. نو زۀ پوهه شوم چې کوم کس به د بادشاه د وفات نه پس په تخت کښېنى نو هغه به صرف د تېر شوى بادشاه په شان حکومت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16356, 'Ecclesiastes 2:13', 'Ecclesiastes', 2, 13, '&nbsp;ما وکتل چې څنګه رڼا د تيارې نه ښۀ ده نو داسې حِکمت د کم عقلتوب نه ښۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16357, 'Ecclesiastes 2:14', 'Ecclesiastes', 2, 14, '&nbsp;ځکه چې هوښيارانو ته دا پته وى چې هغوئ چرته روان دى، خو کم عقلو ته پته نۀ لګى ځکه چې هغوئ په تيارۀ کښې روان وى. خو ما ته دا پته هم ولګېده چې زمونږ د دواړو اَنجام يو دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16358, 'Ecclesiastes 2:15', 'Ecclesiastes', 2, 15, '&nbsp;ما د ځان سره ووئيل، ”د کم عقل په شان اَنجام به زما هم وى، نو بيا زما د ټول حِکمت فائده څۀ ده؟ دا هر څۀ بې‌معنې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16359, 'Ecclesiastes 2:16', 'Ecclesiastes', 2, 16, '&nbsp;ځکه چې هوښيار او کم عقل دواړه به مرى. هوښيار به د کم عقل نه تر زيات وخته پورې ياد نۀ شى ساتلے. په راتلونکى وخت کښې به دواړه هېر کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16360, 'Ecclesiastes 2:17', 'Ecclesiastes', 2, 17, '&nbsp;نو ما د ژوند نه نفرت شروع کړو، ځکه چې دې ما له په دُنيا کښې د تکليف نه بغېر هيڅ هم نۀ وُو راکړى. دا هر څۀ بې‌معنې وُو، هسې هوا پسې منډې وهل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16361, 'Ecclesiastes 2:18', 'Ecclesiastes', 2, 18, '&nbsp;ما چې په مخ د زمکې د هر څۀ دپاره محنت کړے وو نو د هغې نه زما نفرت پېدا شو، ځکه چې دا هر څۀ به هغۀ ته پاتې شى چې زما نه پس به راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16362, 'Ecclesiastes 2:19', 'Ecclesiastes', 2, 19, '&nbsp;او چا ته پته ده چې هغه به هوښيار وى او کۀ کم عقل؟ خو چې ما د څۀ دپاره محنت کړے دے نو هغه هر څۀ به د هغۀ شى، څۀ چې ما په خپله هوښيارتيا په مخ د زمکې ګټلى دى نو هغه هر څۀ به د هغۀ وى. دا ټول بې‌معنې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16363, 'Ecclesiastes 2:20', 'Ecclesiastes', 2, 20, '&nbsp;ما چې په مخ د زمکې کوم سخت محنت کړے وو د هغې نه زۀ مايوسه شوم او زما زړۀ همت بائيلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16364, 'Ecclesiastes 2:21', 'Ecclesiastes', 2, 21, '&nbsp;ځکه چې تۀ به خپل کار په ډېر حِکمت، پوهې او مهارت سره وکړې او بيا به دا هر څۀ هغه چا ته پرېږدې چې هغۀ د دې دپاره هيڅ هم نۀ وى کړى. دا بې‌معنې دى او لويه بد قسمتى ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16365, 'Ecclesiastes 2:22', 'Ecclesiastes', 2, 22, '&nbsp;نو په مخ د زمکې انسان ته د سخت محنت او پرېشانۍ نه څۀ حاصليږى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16366, 'Ecclesiastes 2:23', 'Ecclesiastes', 2, 23, '&nbsp;هره ورځ هغه کړيږى او د خپل کار دپاره پرېشانه وى. او د شپې هم ورته ذهنى سکون نۀ ملاويږى. دا هر څۀ بې‌معنې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16367, 'Ecclesiastes 2:24', 'Ecclesiastes', 2, 24, '&nbsp;د انسان دپاره د ټولو نه ښۀ خبره دا ده چې خوراک څښاک کوى او د خپل محنت نه خوشحاله وى. خو ما ته دا پته هم ولګېده چې دا څيزونه د خُدائ پاک له طرف نه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16368, 'Ecclesiastes 2:25', 'Ecclesiastes', 2, 25, '&nbsp;ځکه چې صرف د خُدائ پاک په مدد سره مونږ خوراک کولے شُو او د ژوند نه مزې اخستے شُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16369, 'Ecclesiastes 2:26', 'Ecclesiastes', 2, 26, '&nbsp;خُدائ پاک هغه چا له حِکمت، پوهه او خوشحالى ورکوى څوک چې هغه رضا کوى. خو خُدائ پاک ګناهګارو له هدف ورکوى چې دولت راټول کړى او بيا يې ترې نه واخلى او هغه چا له يې ورکړى چې څوک هغه رضا کوى. نو دا هم بې‌معنې دى. دا داسې دى لکه چې څوک عبث منډې وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16370, 'Ecclesiastes 3:1', 'Ecclesiastes', 3, 1, '&nbsp;د هر څيز خپل وخت وى، د هر کار دپاره په مخ د زمکې وخت مقرر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16371, 'Ecclesiastes 3:2', 'Ecclesiastes', 3, 2, '&nbsp;د پېدايښت او مرګ دپاره وخت مقرر وى، د فصل کَرلو او د رېبلو دپاره وخت مقرر وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16372, 'Ecclesiastes 3:3', 'Ecclesiastes', 3, 3, '&nbsp;د مړ کولو او روغولو دپاره وخت مقرر وى، د راغورزولو او د آبادولو دپاره وخت مقرر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16373, 'Ecclesiastes 3:4', 'Ecclesiastes', 3, 4, '&nbsp;د غم دپاره او د خوشحالۍ دپاره وخت مقرر وى، د ماتم دپاره او د ګډېدو دپاره وخت مقرر وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16374, 'Ecclesiastes 3:5', 'Ecclesiastes', 3, 5, '&nbsp;د کاڼو خورولو او راغونډولو دپاره وخت مقرر وى، د غاړه وتلو او نۀ غاړه وتلو دپاره وخت مقرر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16375, 'Ecclesiastes 3:6', 'Ecclesiastes', 3, 6, '&nbsp;د تلاش کولو او د تلاش پرېښودلو دپاره وخت مقرر وى، د محفوظ ساتلو دپاره او د غورزولو دپاره وخت مقرر وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16376, 'Ecclesiastes 3:7', 'Ecclesiastes', 3, 7, '&nbsp;د شلولو او د ګنډلو دپاره وخت مقرر وى، د خاموشۍ او د خبرو کولو دپاره وخت مقرر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16377, 'Ecclesiastes 3:8', 'Ecclesiastes', 3, 8, '&nbsp;د مينې کولو دپاره او د نفرت کولو دپاره وخت مقرر وى، د جنګ دپاره او د امن دپاره وخت مقرر وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16378, 'Ecclesiastes 3:9', 'Ecclesiastes', 3, 9, '&nbsp;يو کاريګر د خپل محنت نه څۀ فائده اخلى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16379, 'Ecclesiastes 3:10', 'Ecclesiastes', 3, 10, '&nbsp;ما هغه بوج کتلے دے کوم چې خُدائ پاک په مونږ باندې اېښے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16380, 'Ecclesiastes 3:11', 'Ecclesiastes', 3, 11, '&nbsp;خو خُدائ پاک هر څۀ داسې جوړ کړى دى چې په خپل وخت باندې ښائسته او مناسب وى. هغه انسانانو له د ابديت خيال ورکوى، خو سره د دې مونږ د خُدائ پاک په کار باندې د اول نه واخله تر آخره پورې پوره نۀ شُو پوهېدلے څۀ چې هغه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16381, 'Ecclesiastes 3:12', 'Ecclesiastes', 3, 12, '&nbsp;نو زۀ پوهه شوم چې د ټولو نه ښۀ خبره دا ده چې د ژوند نه مونږ خوندونه او مزې واخلو تر کومې پورې چې مونږ ژوندى يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16382, 'Ecclesiastes 3:13', 'Ecclesiastes', 3, 13, '&nbsp;مونږ ټولو له په کار دى چې خوراک څښاک کوُو او په خپله خوارۍ مزدورۍ کښې خوشحاله اوسو. دا د خُدائ پاک نعمتونه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16383, 'Ecclesiastes 3:14', 'Ecclesiastes', 3, 14, '&nbsp;ما ته پته ده څۀ چې خُدائ پاک کوى نو هغه د همېشه دپاره پاتې کېدونکى وى. په هغې کښې نۀ څۀ کمے کېدے شى او نۀ څۀ زياتے. او دا هر څۀ خُدائ پاک ځکه کوى چې خلق د هغۀ نه يريږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16384, 'Ecclesiastes 3:15', 'Ecclesiastes', 3, 15, '&nbsp;هر څۀ چې اوس کيږى هغه پخوا هم شوى دى، او څۀ چې به په آئنده کښې کيږى، هغه پخوا هم شوى دى. ځکه چې خُدائ پاک دا هر څۀ بيا بيا دوباره کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16385, 'Ecclesiastes 3:16', 'Ecclesiastes', 3, 16, '&nbsp;د دې نه علاوه ما دا هم وکتل، چرته چې مونږ د اِنصاف توقع کوله هلته بدعملى وه، چرته چې مونږ د صداقت توقع کوله هلته بدعملى وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16386, 'Ecclesiastes 3:17', 'Ecclesiastes', 3, 17, '&nbsp;ما په خپل زړۀ کښې ووئيل، خُدائ پاک به د بدعملو او د صادقانو عدالت کوى، ځکه چې هر يو څيز او هر يو کار دپاره يو وخت مقرر دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16387, 'Ecclesiastes 3:18', 'Ecclesiastes', 3, 18, '&nbsp;او ما دا هم په خپل زړۀ کښې ووئيل، چې خُدائ پاک د انسانانو آزمېښت کوى، چې مونږ ته دا وښائى چې مونږ د ځناورو نه ښۀ نۀ يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16388, 'Ecclesiastes 3:19', 'Ecclesiastes', 3, 19, '&nbsp;لنډه دا چې، د انسانانو او ځناورو دواړو اَنجام يو دے، انسان او ځناور دواړه ساه اخلى، او دواړه مرى. انسان د ځناور نه بهتر نۀ دے، دا هر څۀ بې‌معنې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16389, 'Ecclesiastes 3:20', 'Ecclesiastes', 3, 20, '&nbsp;مونږ ټول د مرګ طرف ته روان يُو، مونږ ټول د خاورو نه جوړ يُو او بيا به خاورو ته ځو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16390, 'Ecclesiastes 3:21', 'Ecclesiastes', 3, 21, '&nbsp;څوک دا يقين سره وئيلے شى چې د مرګ نه پس د انسان روح بره ځى او د ځناور روح لاندې زمکې ته ځى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16391, 'Ecclesiastes 3:22', 'Ecclesiastes', 3, 22, '&nbsp;نو بيا ما ته دا پته ولګېده چې د دې نه ښۀ خبره نشته چې په خپل محنت باندې خوشحاله اوسو. د دې نه بغېر بله لار نشته. هيچا ته پته نۀ لګى چې د مرګ نه پس به څۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16392, 'Ecclesiastes 4:1', 'Ecclesiastes', 4, 1, '&nbsp;ما يو ځل بيا نظر واچولو او هغه ټول ظلم مې وليدو کوم چې په مخ د زمکې کيږى. ګوره د مظلومانو وښکې څاڅى خو د تسلۍ ورکولو والا هيڅوک نۀ وى. ظالمان ډېر زورَور دى او مظلومان ډېر بې‌وسه دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16393, 'Ecclesiastes 4:2', 'Ecclesiastes', 4, 2, '&nbsp;نو ما هغه خلق بختور وګڼل کوم چې مړۀ شوى دى، د هغه خلقو نه کوم چې تر اوسه پورې ژوندى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16394, 'Ecclesiastes 4:3', 'Ecclesiastes', 4, 3, '&nbsp;خو د ټولو نه بختور هغه دى کوم چې لا پېدا شوى نۀ دى، چې هغوئ هغه بدعملى نۀ ده ليدلې کومه چې په مخ د زمکې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16395, 'Ecclesiastes 4:4', 'Ecclesiastes', 4, 4, '&nbsp;بيا ما دا هم وکتل چې ټول خلق دې دپاره محنت کوى او د اُستاذۍ نه کار اخلى ځکه چې هغوئ د يو بل سره حسد کوى. خو دا بې‌معنې وى. دا داسې دى لکه چې څوک هوا پسې منډې وهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16396, 'Ecclesiastes 4:5', 'Ecclesiastes', 4, 5, '&nbsp;کم عقل د لاس مشقت پرېږدى او خپل ځان د لوږې وژنى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16397, 'Ecclesiastes 4:6', 'Ecclesiastes', 4, 6, '&nbsp;خېر دے چې لږ وى خو چې د آرام سره وى، نه چې ډېر وى او د بې‌حده محنت سره وى. حد نه زيات محنت هوا پسې منډې وهل دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16398, 'Ecclesiastes 4:7', 'Ecclesiastes', 4, 7, '&nbsp;ما په دُنيا کښې نور څۀ هم ليدلى دى چې هغه بې‌معنې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16399, 'Ecclesiastes 4:8', 'Ecclesiastes', 4, 8, '&nbsp;دا د يو سړى خبره ده څوک چې بلکل يواځې وو. د هغۀ نۀ بچى وُو او نۀ يې خپلوان وُو. هغۀ به هر وخت کار کولو، خو بيا هم هغه په خپله ګټه باندې مطمئن نۀ وو. هغۀ د خپل ځان نه تپوس وکړو، ”د چا دپاره زۀ دومره سخت محنت کوم او خپل ځان د خوشحالۍ نه محروم ساتم؟“ دا هم بې‌معنې دى او د افسوس خبره ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(16400, 'Ecclesiastes 4:9', 'Ecclesiastes', 4, 9, '&nbsp;د يو نه دوه کسان ښۀ وى، ځکه چې هغوئ د خپل محنت نه ښۀ فائده اخستے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');